code:
//! The `bsc studio` subcommand (#2890) — SAVE + read the Studio store (a self-contained snapshot of
//! the app's library state) from a session's own shell. Unlike the plain per-id store shims
//! (`bsc blueprint`/`bsc persona`), `save` AGGREGATES across every sibling library collection, so this
//! is a small custom CLI over [`crate`] rather than a [`bsc_json_store::cli::CliSpec`] shim.
//!
//! Dispatched by the unified `bsc` binary (#1877) via [`run`]; the shared per-command help (#1762):
//!   bsc studio help          # compact menu
//!   bsc studio save help     # detailed help for ONE command
//!
//! `--dir <base>` (or the default `~/.base-studio-code/`) is the BASE dir: `save` reads its sibling
//! collections under it and writes the bundle to `<base>/studios/`; `list`/`get`/`remove` operate on
//! that studios store.

use bsc_cli_util::CmdDoc;
use serde_json::Value;
use std::io::Read;

const TAGLINE: &str =
    "the Studio store — save/list/get/remove ~/.base-studio-code/studios: shareable snapshots of the app's library state (#2890)";

/// The command catalog — drives dispatch validation + the shared help system.
/// The crate's own verb catalog. `pub` so `bsc surface verbs` and the Glance crate drill can PROJECT
/// it rather than restate it — a generated catalog cannot drift, a second list does.
pub const COMMANDS: &[CmdDoc] = &[
    CmdDoc {
        name: "save",
        summary: "snapshot the app's library state into a shareable Studio",
        usage: "\
USAGE:
  bsc studio save <name> [--description <d>] [--dir <base>] [--out <path>]
                         [--all | --scope library|full | --<system>…] [--allow-empty] [--pretty]

Assembles a Studio — a snapshot of the app's state — and writes it. With no scope flags this is the
SHAREABLE library bundle it has always been: the sibling library collections, keyed by system, saved
to <base>/studios/<id>.json. That default is deliberate — the artifact you get without thinking is
the one that is safe to hand to someone.

  --dir <base>    WHICH install to READ. Not where the backup goes.
  --out <path>    WHERE to write it. Defaults to <base>/studios/<id>.json, so every existing
                  invocation behaves exactly as it did before this flag existed.

SCOPE — no flags is the library bundle; otherwise you get exactly what you named:
  --all           everything durable on this machine: the library bundle, every SQLite store, and
                  every per-project plan store. NOT secrets — see below.
  --scope full    the same as --all; --scope library is the default.
  --<system>      one library system by name (--personas, --components, --blueprints, …). Run
                  `bsc studio save help` to see the roster; an unknown name is refused rather than
                  silently matching nothing.
  --plans         the per-project plan stores (issues, changes, discovery).
  --stores        the SQLite stores beside the library collections.

SHAPE: selecting any database-backed system forces a DIRECTORY (studio.json + stores/ + plans/ +
manifest.json), because 28 MB of SQLite cannot live inside a JSON bundle. An --out naming a .json
path is then REFUSED, naming what forced the directory, rather than silently writing a directory
where a file was asked for.

REFUSALS, because a backup that appears to succeed and holds nothing is the worst outcome this verb
has: a source whose every store is empty is refused unless --allow-empty, and the message names what
it found bare. --dir pointing somewhere empty is the usual cause.

SECRETS ARE NEVER CAPTURED — not by --all, not by a scope, not by naming them. The values live in the
OS keychain, but which services you are paired with is itself disclosure, and a backup is the artifact
most likely to travel. Restoring those rows on another machine would describe pairings that machine
does not have, which is worse than having none.

Every other store is captured by DISCOVERY, not from a list, so a store added by a future release is
backed up without anyone remembering to add it.",
    },
    CmdDoc {
        name: "set",
        summary: "upsert a full Studio bundle from JSON on stdin; prints its id",
        usage: "\
USAGE:
  bsc studio set [--dir <base>] [--pretty]   # a full Studio bundle (one JSON object) on stdin

Upserts a Studio by its (required, non-empty) \"id\" field — the write half of gist IMPORT (#2891).
The bundle must be a JSON object carrying a non-empty \"id\" AND \"name\"; the captured snapshot rides
through as given. A same-id bundle overwrites (upsert). Reads the bundle from stdin; prints the id
written. --dir overrides the base ~/.base-studio-code dir (writes to <base>/studios/).",
    },
    CmdDoc {
        name: "apply",
        summary: "re-seed the app's libraries from a saved Studio (REPLACES the captured systems)",
        usage: "\
USAGE:
  bsc studio apply <id> [--dir <base>] [--pretty]

Re-seeds the app's libraries from the saved Studio <id>. For EACH system captured in the studio's
snapshot (teams · personas · components · kits · variants · themes · blueprints), REPLACES that
system's store — every existing record is removed, then the studio's records are written in. A system
the snapshot does NOT contain is left untouched (a partial studio is safe). DESTRUCTIVE: the current
libraries for the captured systems are overwritten — save the current state first if you want a
rollback point. Prints a summary { applied: { <system>: <count> }, id, name } (compact; --pretty
indents). --dir overrides the base ~/.base-studio-code dir.",
    },
    CmdDoc {
        name: "list",
        summary: "every saved Studio's {id, name} (JSON)",
        usage: "\
USAGE:
  bsc studio list [--dir <base>] [--pretty]

Prints every saved Studio's { id, name } as JSON (compact; --pretty for indented). The full bundle —
identity + the captured snapshot — is one `get <id>` away.",
    },
    CmdDoc {
        name: "get",
        summary: "print one Studio bundle (JSON) or null",
        usage: "\
USAGE:
  bsc studio get <id> [--dir <base>] [--pretty]

Prints the full stored Studio bundle for <id> (identity + snapshot) as JSON, or `null` if absent.",
    },
    CmdDoc {
        name: "verify",
        summary: "re-check a saved backup WITHOUT restoring it",
        usage: "\
USAGE:
  bsc studio verify --from <dir> [--pretty]

Answers \"is that backup still good?\" without touching anything. Opens every captured database and
runs `PRAGMA integrity_check`, then compares the directory against its own manifest IN BOTH
DIRECTIONS — a file the manifest promised and lost, and a file on disk it never mentioned, are both
disagreements. Exits non-zero when the backup does not verify.

Re-derived from the files every time, never read back from the manifest's own claims: a backup that
can only repeat what it said when it was written cannot tell you it has rotted since.",
    },
    CmdDoc {
        name: "restore",
        summary: "put a backup's stores and plan stores back",
        usage: "\
USAGE:
  bsc studio restore --from <dir> [--dir <base>] [--dry-run] [--force] [--pretty]

Restores `stores/*.db` and `plans/*.db` from a full backup into <base> (default
~/.base-studio-code). --from is the backup; --dir is where it lands.

  --dry-run   report every write and perform NONE of them. Start here.
  --force     write over stores that already exist at the destination.

TWO REFUSALS, both because a bad restore destroys what it was meant to save:

  A NON-EMPTY DESTINATION is refused, naming what it would have overwritten. The likeliest moment to
  run this verb wrongly is in a panic, pointed at the machine that still has the data on it.

  A BACKUP THAT DOES NOT VERIFY is refused WHOLE rather than applied in part — after a partial
  restore nobody can tell which half landed. `verify` runs first, every time.

Restoring does NOT bring back credentials: `secrets.db` is captured by no scope and no flag, so the
report names it as never-captured rather than leaving you to assume your pairings returned.",
    },
    CmdDoc {
        name: "remove",
        summary: "delete a Studio (no-op if absent)",
        usage: "\
USAGE:
  bsc studio remove <id> [--dir <base>] [--pretty]

Deletes the Studio keyed by <id>. A no-op (not an error) when it does not exist.",
    },
];

/// Parsed global flags + leftover positional args.
#[derive(Debug)]
struct Args {
    dir: Option<String>,
    out: Option<String>,
    description: Option<String>,
    scope: Option<String>,
    /// Library systems named one flag at a time (`--personas`). Empty means "not restricted".
    systems: Vec<String>,
    databases: bool,
    all: bool,
    from: Option<String>,
    dry_run: bool,
    force: bool,
    allow_empty: bool,
    pretty: bool,
    positional: Vec<String>,
}

fn parse_args(raw: Vec<String>) -> Result<Args, String> {
    let mut a = Args {
        dir: None,
        out: None,
        description: None,
        scope: None,
        systems: Vec::new(),
        databases: false,
        all: false,
        from: None,
        dry_run: false,
        force: false,
        allow_empty: false,
        pretty: false,
        positional: Vec::new(),
    };
    let mut it = raw.into_iter();
    while let Some(arg) = it.next() {
        match arg.as_str() {
            "--dir" => a.dir = Some(it.next().ok_or("--dir needs a path")?),
            "--out" => a.out = Some(it.next().ok_or("--out needs a path")?),
            "--description" => a.description = Some(it.next().ok_or("--description needs a value")?),
            "--scope" => a.scope = Some(it.next().ok_or("--scope needs library|full")?),
            "--all" => a.all = true,
            "--from" => a.from = Some(it.next().ok_or("--from needs a backup directory")?),
            "--dry-run" => a.dry_run = true,
            "--force" => a.force = true,
            "--allow-empty" => a.allow_empty = true,
            "--plans" | "--stores" => a.databases = true,
            "--pretty" => a.pretty = true,
            // `-h`/`--help` route to the help command (anywhere on the line).
            "-h" | "--help" => a.positional.insert(0, "help".into()),
            // A PER-SYSTEM flag, matched against the roster rather than written out one arm per
            // system. A new system in `bsc_studio::SYSTEMS` gains its flag with no code here — which
            // is the point, since the roster guard exists to stop exactly that kind of drift.
            other if other.starts_with("--")
                && bsc_studio_systems().iter().any(|k| *k == other.trim_start_matches("--")) =>
            {
                a.systems.push(other.trim_start_matches("--").to_string());
            }
            other if other.starts_with("--") => {
                return Err(format!(
                    "unknown flag '{other}' (library systems: {}; see `save help`)",
                    bsc_studio_systems().join(", ")
                ))
            }
            _ => a.positional.push(arg),
        }
    }
    Ok(a)
}

/// The per-system flag list, rendered from the roster at run time.
///
/// Tagged shareable vs private so the reader can tell, without leaving the help, which flags produce
/// an artifact that is safe to hand to someone. `secrets` appears here NAMED AS UNAVAILABLE rather
/// than omitted: a reader who does not see it cannot tell whether it is covered by `--all` or
/// deliberately excluded, and that ambiguity is the thing worth removing.
fn system_flag_help() -> String {
    let mut out = String::from("SYSTEMS (generated from this build's roster):\n");
    for key in bsc_studio_systems() {
        out.push_str(&format!("  --{key:<14} shareable\n"));
    }
    out.push_str("  --plans          private — per-project issues, changes and discovery\n");
    out.push_str("  --stores         private — the SQLite stores beside the library collections\n");
    for (name, why) in crate::NEVER_CAPTURED {
        out.push_str(&format!("  (--{name:<12} UNAVAILABLE — {why})\n"));
    }
    out
}

/// The library-system keys, from the crate roster. One source, so the flag list cannot lie about
/// what this build can actually capture.
fn bsc_studio_systems() -> Vec<&'static str> {
    crate::SYSTEMS.iter().map(|(key, _, _)| *key).collect()
}

/// Print a JSON value to stdout, compact by default (`pretty` indents).
fn print_value(v: &Value, pretty: bool) -> Result<(), String> {
    let s = if pretty { serde_json::to_string_pretty(v) } else { serde_json::to_string(v) };
    println!("{}", s.map_err(|e| e.to_string())?);
    Ok(())
}

/// The `studio` subcommand entrypoint: `args` is everything after `bsc studio`; `prog` is the display
/// name for help/errors. Handles help before resolving the base dir.
pub fn run(args: Vec<String>, prog: &str) -> Result<(), String> {
    let args = parse_args(args)?;

    // Top-level + per-command help, run BEFORE resolving the base (help works without a base dir).
    if bsc_cli_util::handle_help(prog, TAGLINE, COMMANDS, &args.positional) {
        // The system flags are printed FROM THE ROSTER, not from the usage string above. A
        // hand-written list is a second source that drifts the moment a system is added — and the
        // one thing an agent reads to decide what it may call must not be able to lie about what
        // this build can capture.
        if args.positional.iter().any(|a| a == "save") {
            println!("{}", system_flag_help());
        }
        return Ok(());
    }

    let base = crate::resolve_base(&args.dir)?;
    let cmd = args.positional.first().cloned().unwrap_or_default();

    match cmd.as_str() {
        "save" => {
            let name = args
                .positional
                .get(1)
                .ok_or_else(|| format!("usage: {prog} save <name> [--description <d>] [--out <path>] [--all]"))?;

            let scope = match args.scope.as_deref() {
                Some(s) => Some(crate::Scope::parse(s)?),
                None => None,
            };
            let full = args.all || scope == Some(crate::Scope::Full) || args.databases;

            // THE UNCHANGED PATH. No --out, no scope flags, no system flags: byte-for-byte what
            // `save` did before any of this existed, straight into the studios store.
            if !full && args.out.is_none() && args.systems.is_empty() {
                let studio = crate::save(&base, name, args.description)?;
                let v = serde_json::to_value(&studio).map_err(|e| e.to_string())?;
                return print_value(&v, args.pretty);
            }

            let opts = crate::BackupOptions {
                description: args.description,
                allow_empty: args.allow_empty,
                systems: (!args.systems.is_empty()).then_some(args.systems),
                databases: full,
            };
            let out = match args.out {
                Some(p) => std::path::PathBuf::from(p),
                // No --out with a scope flag still needs a destination; keep it beside the store so
                // the default never depends on a flag the caller did not pass.
                None if full => base.join("studios").join(crate::slug(name)?),
                None => base.join("studios").join(format!("{}.json", crate::slug(name)?)),
            };
            let manifest = crate::backup(&base, &out, name, &opts)?;
            let mut v = serde_json::to_value(&manifest).map_err(|e| e.to_string())?;
            if let Some(obj) = v.as_object_mut() {
                obj.insert("out".into(), Value::String(out.display().to_string()));
            }
            print_value(&v, args.pretty)
        }
        "set" => {
            // Read the full Studio bundle from stdin (the write half of gist import, #2891).
            let mut json = String::new();
            std::io::stdin()
                .read_to_string(&mut json)
                .map_err(|e| format!("reading stdin: {e}"))?;
            let id = crate::set(&base, &json)?;
            print_value(&Value::String(id), args.pretty)
        }
        "apply" => {
            let id = args.positional.get(1).ok_or_else(|| format!("usage: {prog} apply <id>"))?;
            let summary = crate::apply(&base, id)?;
            print_value(&summary, args.pretty)
        }
        "list" => print_value(&Value::Array(crate::list_meta(&base)), args.pretty),
        "get" => {
            let id = args.positional.get(1).ok_or_else(|| format!("usage: {prog} get <id>"))?;
            match crate::get(&base, id)? {
                Some(v) => print_value(&v, args.pretty),
                None => {
                    println!("null");
                    Ok(())
                }
            }
        }
        "remove" => {
            let id = args.positional.get(1).ok_or_else(|| format!("usage: {prog} remove <id>"))?;
            crate::remove(&base, id)?;
            print_value(&Value::String(id.clone()), args.pretty)
        }
        "verify" => {
            let from = args
                .from
                .ok_or_else(|| format!("usage: {prog} verify --from <backup-dir>"))?;
            let report = crate::verify_backup(std::path::Path::new(&from))?;
            let ok = report.ok;
            let v = serde_json::to_value(&report).map_err(|e| e.to_string())?;
            print_value(&v, args.pretty)?;
            // A verify that FAILS must fail the process. A backup checker whose bad news is only
            // visible by reading its JSON is a checker nothing can be scripted around.
            if ok {
                Ok(())
            } else {
                Err(format!(
                    "{from} does not verify — missing: {:?}, corrupt: {:?}, unexpected: {:?}",
                    report.missing, report.corrupt, report.unexpected
                ))
            }
        }
        "restore" => {
            let from = args
                .from
                .ok_or_else(|| format!("usage: {prog} restore --from <backup-dir> [--dry-run]"))?;
            let opts = crate::RestoreOptions { dry_run: args.dry_run, force: args.force };
            let report = crate::restore_backup(std::path::Path::new(&from), &base, &opts)?;
            let v = serde_json::to_value(&report).map_err(|e| e.to_string())?;
            print_value(&v, args.pretty)
        }
        other => Err(bsc_cli_util::unknown_command(prog, TAGLINE, COMMANDS, other)),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parse_args_reads_flags_and_positionals() {
        let a = parse_args(vec![
            "save".into(),
            "My Studio".into(),
            "--description".into(),
            "notes".into(),
            "--dir".into(),
            "/tmp/base".into(),
            "--pretty".into(),
        ])
        .unwrap();
        assert_eq!(a.positional, vec!["save".to_string(), "My Studio".to_string()]);
        assert_eq!(a.description.as_deref(), Some("notes"));
        assert_eq!(a.dir.as_deref(), Some("/tmp/base"));
        assert!(a.pretty);
        assert!(parse_args(vec!["--nope".into()]).is_err(), "unknown flag rejected");
        assert!(parse_args(vec!["--dir".into()]).is_err(), "--dir needs a value");
    }

    #[test]
    fn parse_args_routes_help_flag_to_the_help_command() {
        let a = parse_args(vec!["--help".into()]).unwrap();
        assert_eq!(a.positional.first().map(String::as_str), Some("help"));
    }

    #[test]
    fn help_overview_lists_commands_and_per_command_help_drills_in() {
        let ov = bsc_cli_util::help_overview("bsc studio", TAGLINE, COMMANDS);
        for c in ["save", "set", "apply", "list", "get", "remove"] {
            assert!(ov.contains(c), "overview lists {c}");
        }
        let one = bsc_cli_util::help_for("bsc studio", TAGLINE, COMMANDS, "save");
        assert!(one.contains("bsc studio save"));
        assert!(one.contains("snapshot"));
        // `apply` (#2893) drills in with its REPLACE semantics.
        let apply_help = bsc_cli_util::help_for("bsc studio", TAGLINE, COMMANDS, "apply");
        assert!(apply_help.contains("bsc studio apply"));
        assert!(apply_help.contains("REPLACES"));
        // `set` (#2891) drills in with its stdin usage.
        let set_help = bsc_cli_util::help_for("bsc studio", TAGLINE, COMMANDS, "set");
        assert!(set_help.contains("bsc studio set"));
        assert!(set_help.contains("stdin"));
        // An unknown command falls back to the overview.
        assert!(bsc_cli_util::help_for("bsc studio", TAGLINE, COMMANDS, "nope").contains("COMMANDS:"));
    }

    #[test]
    fn run_help_paths_need_no_base_dir() {
        // help/no-command must work without resolving a base (BEFORE any store read).
        assert!(run(vec!["help".into()], "bsc studio").is_ok());
        assert!(run(vec![], "bsc studio").is_ok());
        assert!(run(vec!["save".into(), "help".into()], "bsc studio").is_ok());
        // `set help` must resolve as help (not fall through to the stdin-reading dispatch arm).
        assert!(run(vec!["set".into(), "help".into()], "bsc studio").is_ok());
        assert!(run(vec!["apply".into(), "help".into()], "bsc studio").is_ok());
    }

    #[test]
    fn run_apply_re_seeds_a_system_store_over_a_temp_base() {
        // End-to-end through the CLI dispatch: seed a live store, save it as a studio under a fresh
        // name, wipe the live store, then `apply` the studio to bring the records back.
        use std::sync::atomic::{AtomicU64, Ordering};
        static N: AtomicU64 = AtomicU64::new(0);
        let base = std::env::temp_dir().join(format!(
            "bsc-studio-cli-apply-{}-{}",
            std::process::id(),
            N.fetch_add(1, Ordering::Relaxed)
        ));
        let _ = std::fs::remove_dir_all(&base);
        let dir = base.to_string_lossy().into_owned();

        let bp = bsc_json_store::Store::new(base.join("blueprints"), "blueprint");
        bp.set("a", r#"{"id":"a","name":"A"}"#).unwrap();
        run(vec!["save".into(), "Snap".into(), "--dir".into(), dir.clone()], "bsc studio").unwrap();
        // Diverge the live store from the snapshot: drop the captured one, add an unrelated one.
        bp.remove("a").unwrap();
        bp.set("z", r#"{"id":"z","name":"Z"}"#).unwrap();

        run(vec!["apply".into(), "snap".into(), "--dir".into(), dir.clone()], "bsc studio").unwrap();
        // The store now mirrors the snapshot exactly: `a` back, `z` (not captured) gone.
        let ids: std::collections::BTreeSet<String> = bp
            .list()
            .iter()
            .filter_map(|j| serde_json::from_str::<Value>(j).ok())
            .filter_map(|v| v["id"].as_str().map(str::to_string))
            .collect();
        assert_eq!(ids, ["a".to_string()].into_iter().collect());
        // A missing positional errors with a usage line; an absent id errors from the core.
        assert!(run(vec!["apply".into(), "--dir".into(), dir.clone()], "bsc studio").is_err());
        assert!(run(vec!["apply".into(), "absent".into(), "--dir".into(), dir], "bsc studio").is_err());
    }

    #[test]
    fn run_save_then_get_and_list_over_a_temp_base() {
        // End-to-end through the CLI dispatch with an explicit --dir base (no user store touched).
        use std::sync::atomic::{AtomicU64, Ordering};
        static N: AtomicU64 = AtomicU64::new(0);
        let base = std::env::temp_dir().join(format!(
            "bsc-studio-cli-run-{}-{}",
            std::process::id(),
            N.fetch_add(1, Ordering::Relaxed)
        ));
        let _ = std::fs::remove_dir_all(&base);
        let dir = base.to_string_lossy().into_owned();

        run(vec!["save".into(), "Demo Kit".into(), "--dir".into(), dir.clone()], "bsc studio").unwrap();
        // It landed under <base>/studios and reads back as the full bundle.
        let got = crate::get(&base, "demo-kit").unwrap().expect("saved");
        assert_eq!(got["name"], "Demo Kit");
        // The CLI dispatch paths for list/get/remove don't error.
        assert!(run(vec!["list".into(), "--dir".into(), dir.clone()], "bsc studio").is_ok());
        assert!(run(vec!["get".into(), "demo-kit".into(), "--dir".into(), dir.clone()], "bsc studio").is_ok());
        assert!(run(vec!["get".into(), "absent".into(), "--dir".into(), dir.clone()], "bsc studio").is_ok());
        assert!(run(vec!["remove".into(), "demo-kit".into(), "--dir".into(), dir.clone()], "bsc studio").is_ok());
        assert_eq!(crate::get(&base, "demo-kit").unwrap(), None, "remove landed");
        // A missing positional errors with a usage line.
        assert!(run(vec!["save".into(), "--dir".into(), dir.clone()], "bsc studio").is_err());
        assert!(run(vec!["get".into(), "--dir".into(), dir], "bsc studio").is_err());
    }

    /// A scratch base holding one real record, so a save has something to find.
    fn seeded_base(tag: &str) -> std::path::PathBuf {
        use std::sync::atomic::{AtomicU64, Ordering};
        static N: AtomicU64 = AtomicU64::new(0);
        let base = std::env::temp_dir().join(format!(
            "bsc-studio-flags-{tag}-{}-{}",
            std::process::id(),
            N.fetch_add(1, Ordering::Relaxed)
        ));
        let _ = std::fs::remove_dir_all(&base);
        std::fs::create_dir_all(&base).expect("scratch");
        // One persona, so `source_is_bare` sees real content and the empty-refusal stays out of the way.
        bsc_json_store::Store::new(base.join("personas"), "persona")
            .set("p1", "{\"id\":\"p1\",\"name\":\"Ada\"}")
            .expect("seed a record");
        base
    }

    /// EVERY system in the roster has a working flag, and it is derived FROM the roster.
    ///
    /// The acceptance criterion is "generated from the roster rather than hand-written per system",
    /// and this is what makes that checkable: it loops the roster, so adding a system without a flag
    /// fails here rather than being discovered by a user whose `--sounds` was rejected.
    #[test]
    fn every_library_system_has_a_flag_taken_from_the_roster() {
        for (key, _, _) in crate::SYSTEMS {
            let a = parse_args(vec![format!("--{key}")]).unwrap_or_else(|e| panic!("--{key}: {e}"));
            assert_eq!(a.systems, vec![key.to_string()], "--{key} must select exactly its own system");
        }
        assert_eq!(bsc_studio_systems().len(), crate::SYSTEMS.len(), "the flag list IS the roster");
    }

    /// The help's system list is GENERATED, so it cannot drift from what the build can capture.
    #[test]
    fn the_help_lists_every_system_from_the_roster_and_names_what_it_cannot_take() {
        let help = system_flag_help();
        for (key, _, _) in crate::SYSTEMS {
            assert!(help.contains(&format!("--{key}")), "the help must list --{key}: {help}");
        }
        for (name, _) in crate::NEVER_CAPTURED {
            assert!(
                help.contains(&format!("--{name}")) && help.contains("UNAVAILABLE"),
                "a store that can never be captured must be NAMED as unavailable, not omitted \
                 — otherwise a reader cannot tell it from one --all covers: {help}"
            );
        }
        assert!(help.contains("shareable") && help.contains("private"), "each flag is tagged: {help}");
    }

    /// A misspelled system flag is REFUSED and names the real ones — never silently ignored, which
    /// would produce an empty bundle from a typo.
    #[test]
    fn an_unknown_system_flag_is_refused_and_lists_the_real_ones() {
        let err = parse_args(vec!["--persona".into()]).expect_err("a typo must not be accepted");
        assert!(err.contains("unknown flag '--persona'"), "{err}");
        assert!(err.contains("personas"), "and it must name the real systems: {err}");
    }

    /// `--out` redirects the artifact; omitting it is byte-identical to the old behaviour.
    #[test]
    fn out_writes_where_it_is_told_and_omitting_it_changes_nothing() {
        let base = seeded_base("out");
        let dir = base.to_string_lossy().into_owned();

        // Omitted: lands in the studios store exactly as before.
        run(vec!["save".into(), "Kit".into(), "--dir".into(), dir.clone()], "bsc studio").unwrap();
        let unchanged = crate::get(&base, "kit").unwrap().expect("the default path is untouched");
        assert_eq!(unchanged["name"], "Kit");

        // Given: lands there instead, at exactly the path asked for.
        let out = base.join("elsewhere").join("kit.json");
        run(
            vec![
                "save".into(), "Kit".into(),
                "--dir".into(), dir,
                "--out".into(), out.to_string_lossy().into_owned(),
            ],
            "bsc studio",
        )
        .unwrap();
        assert!(out.is_file(), "--out must create parent dirs and write the bundle there");
        let text = std::fs::read_to_string(&out).unwrap();
        assert!(text.contains("\"name\": \"Kit\""), "and it must be the bundle: {text:.120}");
        std::fs::remove_dir_all(&base).ok();
    }

    /// `--out` at a .json path is REFUSED when a database-backed system is selected, and the refusal
    /// says what forced the directory. Silently writing a directory where a file was asked for would
    /// break the caller's next step.
    #[test]
    fn a_json_out_is_refused_when_the_databases_are_selected() {
        let base = seeded_base("shape");
        let dir = base.to_string_lossy().into_owned();
        let err = run(
            vec![
                "save".into(), "Kit".into(),
                "--dir".into(), dir,
                "--all".into(),
                "--out".into(), base.join("x.json").to_string_lossy().into_owned(),
            ],
            "bsc studio",
        )
        .expect_err("a .json --out with --all must be refused");
        assert!(err.contains("names a .json file"), "{err}");
        assert!(err.contains("DIRECTORY"), "and say what shape it needs: {err}");
        std::fs::remove_dir_all(&base).ok();
    }

    /// `--all` captures the databases; the credential store is still absent from the artifact.
    #[test]
    fn all_captures_the_databases_and_never_the_credential_store() {
        let base = seeded_base("all");
        let dir = base.to_string_lossy().into_owned();
        bsc_json_store::Store::new(base.join("secrets"), "secret")
            .set("s1", "{\"id\":\"s1\",\"service\":\"github\"}")
            .expect("seed");
        let out = base.join("full-backup");
        run(
            vec![
                "save".into(), "Everything".into(),
                "--dir".into(), dir,
                "--all".into(),
                "--out".into(), out.to_string_lossy().into_owned(),
            ],
            "bsc studio",
        )
        .unwrap();
        assert!(out.join("studio.json").is_file(), "the bundle");
        assert!(out.join("manifest.json").is_file(), "and a manifest describing the capture");
        assert!(out.join("stores/personas.db").is_file(), "a discovered store is captured");
        assert!(
            !out.join("stores/secrets.db").exists(),
            "--all must NOT reach the credential store"
        );
        std::fs::remove_dir_all(&base).ok();
    }

    /// An all-empty source is refused through the CLI too, with the override named.
    #[test]
    fn the_cli_refuses_an_empty_source_and_names_the_override() {
        use std::sync::atomic::{AtomicU64, Ordering};
        static N: AtomicU64 = AtomicU64::new(0);
        let base = std::env::temp_dir().join(format!(
            "bsc-studio-empty-{}-{}",
            std::process::id(),
            N.fetch_add(1, Ordering::Relaxed)
        ));
        let _ = std::fs::remove_dir_all(&base);
        std::fs::create_dir_all(&base).unwrap();
        let out = base.join("backup");
        let err = run(
            vec![
                "save".into(), "Nothing".into(),
                "--dir".into(), base.to_string_lossy().into_owned(),
                "--all".into(),
                "--out".into(), out.to_string_lossy().into_owned(),
            ],
            "bsc studio",
        )
        .expect_err("an empty source must be refused");
        assert!(err.contains("--allow-empty"), "{err}");
        assert!(!out.exists(), "and nothing may be written");
        std::fs::remove_dir_all(&base).ok();
    }

}

